import React from 'react';

/** Visual variant for the CitationCard. */
export type CitationCardVariant = 'compact' | 'inline';

/** Props for the {@link CitationCard} component. */
export interface CitationCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Citation index number displayed in the icon badge. */
  index?: number;
  /** Source name / title. */
  source: string;
  /** Snippet / excerpt from the source. */
  snippet?: string;
  /** URL of the source. */
  href?: string;
  /** Metadata strings (e.g. date, page number). */
  meta?: string[];
  /** Visual variant. */
  variant?: CitationCardVariant;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Source reference card with ASCII metadata display.
 * Renders a `<div>` (or `<a>` when `href` is provided) with `sk-citation-card`.
 */
export const CitationCard = React.forwardRef<HTMLDivElement, CitationCardProps>(
  ({ index, source, snippet, href, meta, variant, className, ...rest }, ref) => {
    const Tag = href ? 'a' : 'div';
    const linkProps = href ? { href, target: '_blank', rel: 'noopener noreferrer' } : {};
    return (
      <Tag
        ref={ref as React.Ref<HTMLDivElement & HTMLAnchorElement>}
        className={`sk-citation-card${className ? ` ${className}` : ''}`}
        data-variant={variant}
        {...linkProps}
        {...(rest as React.HTMLAttributes<HTMLElement>)}
      >
        <span className="sk-citation-card__icon">{index ?? '#'}</span>
        <div className="sk-citation-card__content">
          <span className="sk-citation-card__source">{source}</span>
          {snippet && <p className="sk-citation-card__snippet">{snippet}</p>}
          {meta && meta.length > 0 && (
            <div className="sk-citation-card__meta">
              {meta.map((m, i) => (
                <span key={i}>{m}</span>
              ))}
            </div>
          )}
        </div>
      </Tag>
    );
  },
);

CitationCard.displayName = 'CitationCard';

/**
 * skeehn — CitationCard Component
 *
 * @component sk-citation-card
 * @variants  default | compact | inline
 * @slots     __icon __content __source __snippet __meta
 * @a11y      Link semantics, focus ring, truncated text with title attribute
 * @design    Bigger index badge, readable snippet (3 lines, sans), readable metadata.
 */

.sk-citation-card {
  display: inline-flex; align-items: flex-start; gap: var(--sk-space-2);
  padding: var(--sk-space-2) var(--sk-space-3);
  border: var(--sk-border); border-radius: var(--sk-radius-sm);
  background: hsl(var(--sk-muted) / 0.5);
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs);
  margin: var(--sk-space-1) 0;
  text-decoration: none;
  transition: background var(--sk-transition-fast), transform var(--sk-transition-fast), border-color var(--sk-transition-fast);
}
.sk-citation-card:hover { background: hsl(var(--sk-muted)); border-color: hsl(var(--sk-accent) / 0.5); transform: translateY(-1px); }
.sk-citation-card:active { transform: translateY(0); }
.sk-citation-card:focus-visible { outline: var(--sk-focus-ring); outline-offset: var(--sk-focus-ring-offset); }

.sk-citation-card__icon {
  flex-shrink: 0; width: 1.5rem; height: 1.5rem;
  display: flex; align-items: center; justify-content: center;
  background: hsl(var(--sk-accent)); color: hsl(var(--sk-accent-foreground));
  border-radius: var(--sk-radius-sm); font-size: var(--sk-font-size-xs); font-weight: 700;
}
.sk-citation-card__content { flex: 1; min-width: 0; }
.sk-citation-card__source { font-weight: 600; color: hsl(var(--sk-foreground)); letter-spacing: var(--sk-letter-spacing-wide); }
.sk-citation-card__snippet {
  margin-top: var(--sk-space-1);
  font-family: var(--sk-font-sans); font-size: var(--sk-font-size-sm);
  color: hsl(var(--sk-muted-foreground)); line-height: var(--sk-line-height);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.sk-citation-card__meta { margin-top: var(--sk-space-1); display: flex; gap: var(--sk-space-2); font-size: var(--sk-font-size-xs); color: hsl(var(--sk-muted-foreground) / 0.75); }

.sk-citation-card[data-variant="compact"] { padding: var(--sk-space-1) var(--sk-space-2); }
.sk-citation-card[data-variant="compact"] .sk-citation-card__snippet { -webkit-line-clamp: 1; }
.sk-citation-card[data-variant="inline"] { display: inline-flex; padding: 0.1em var(--sk-space-2); border: none; background: transparent; font-size: inherit; vertical-align: baseline; }
.sk-citation-card[data-variant="inline"] .sk-citation-card__icon { width: 1rem; height: 1rem; font-size: 0.5rem; }
.sk-citation-card[data-variant="inline"] .sk-citation-card__snippet,
.sk-citation-card[data-variant="inline"] .sk-citation-card__meta { display: none; }

.sk-citation-card[data-loading] { pointer-events: none; opacity: 0.6; }
.sk-citation-card[data-skeleton] .sk-citation-card__source,
.sk-citation-card[data-skeleton] .sk-citation-card__snippet {
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite; border-radius: var(--sk-radius-sm);
}

@media print {
  .sk-citation-card { border: 1px solid hsl(var(--sk-foreground)); }
  .sk-citation-card[data-skeleton] { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .sk-citation-card { transition: none; }
  .sk-citation-card:hover { transform: none; }
  .sk-citation-card[data-skeleton] .sk-citation-card__source,
  .sk-citation-card[data-skeleton] .sk-citation-card__snippet { animation: none; background: hsl(var(--sk-muted)); }
}
